def parse(payload):
    children=payload.get('children',[])
    if not isinstance(children,list):raise ValueError('CHILDREN_INVALID')
    parent=payload.get('parent')
    if not parent:
        if children:parent='repaired-root'
        else:raise ValueError('PARENT_REQUIRED')
    return {'parent':parent,'children':list(children)}

